import librosa, numpy as np
p='recording.wav'; y,sr=librosa.load(p,sr=None,mono=True)
print(sr,len(y)/sr, np.max(np.abs(y)),np.sqrt(np.mean(y*y)))
for hop in [128,256,512]:
 env=librosa.onset.onset_strength(y=y,sr=sr,hop_length=hop)
 for delta in [0.05,0.1,0.2,0.3]:
